import test from 'node:test';
import assert from 'node:assert/strict';
import path from 'node:path';
import fs from 'node:fs/promises';
import os from 'node:os';
import {spawn} from 'node:child_process';
import {createHash} from 'node:crypto';
import {ZgService} from './zg-service.js';
import {DesignerStore} from './store.js';
import {KnowledgeService,MAX_KNOWLEDGE_FILE_BYTES,LOCAL_PROJECTION_BYTES} from './knowledge-service.js';

// Composed-FS fixture, independent from production filesystem and other test modules.
class MemoryFS {
  files=new Map();aliases=new Map();counter=0;reads=[];writes=[];beforeWrite=null;
  async resolve(value,{cwd='/workspace'}={}){let full=path.resolve(cwd,value);for(const [from,to] of this.aliases)if(full===from||full.startsWith(from+'/'))full=to+full.slice(from.length);return {targetKey:full};}
  processPath(target){return target.targetKey;}
  contains(parent,child){return child.targetKey===parent.targetKey||child.targetKey.startsWith(parent.targetKey+'/');}
  async stat(target){const f=this.files.get(target.targetKey);if(f)return {type:'file',size:f.bytes.length,version:f.version};if(target.targetKey==='/workspace'||[...this.files.keys()].some(p=>p.startsWith(target.targetKey+'/')))return {type:'directory',version:'dir'};}
  async readText(target){this.reads.push(target.targetKey);const f=this.files.get(target.targetKey);if(!f)throw Object.assign(new Error('Missing'),{code:'FS_NOT_FOUND'});return f.bytes.toString('utf8');}
  async listDir(target){const names=new Map();for(const p of this.files.keys())if(p.startsWith(target.targetKey+'/')){const rest=p.slice(target.targetKey.length+1),name=rest.split('/')[0];names.set(name,{name,type:rest.includes('/')?'directory':'file'});}return [...names.values()];}
  put(target,bytes){this.files.set(typeof target==='string'?target:target.targetKey,{bytes:Buffer.from(bytes),version:String(++this.counter)});}
  async writeText(target,content,intent,signal,policy){signal?.throwIfAborted();if(!policy||policy.mode==='read-only'||policy.mode==='workspace-write'&&!this.contains({targetKey:policy.workspaceRoot},target))throw Object.assign(new Error('Denied'),{code:'FS_SANDBOX_DENIED'});await this.beforeWrite?.(target,content);const previous=this.files.get(target.targetKey);if(intent.kind==='createIfAbsent'&&previous||intent.kind==='replaceIfVersion'&&previous?.version!==intent.version)throw Object.assign(new Error('Stale'),{code:'FS_STALE_VERSION'});this.put(target,content);this.writes.push(target.targetKey);return {version:this.files.get(target.targetKey).version};}
}
const policy={mode:'workspace-write',workspaceRoot:'/workspace'},user={user:true,policy};
function fixture(){
  const fs=new MemoryFS(),calls=[],ctx={fs,connection:{requestRejection:()=>undefined,admit:()=>({peer:{principal:{kind:'owner'},signal:new AbortController().signal}})}},store=new DesignerStore({fs,workspaceRoot:'/workspace',policy:()=>policy});
  // Protocol double only: it supplies chosen receipts/hits and does not implement zg retrieval.
  const engine={async runtimeStatus(env){calls.push(['runtime',env]);return {engine:'zg',available:true,model:{id:'local/potion-code-16m-v2',state:'ready',local:true},indexRequiresModel:true,queryReadonly:true};},async setup(input,env){calls.push(['setup',input,env]);return {jobId:'model-1',state:'running'};},async cancel(input,env){calls.push(['cancel',input,env]);return {jobId:input.jobId,state:'cancelled'};},async index(input,env){calls.push(['index',input,env]);env.onProgress?.({phase:'indexing',completed:input.files.length,total:input.files.length});return {engine:'zg',knowledgeId:input.knowledgeId,sourceVersion:input.sourceVersion,indexId:'index-'+input.sourceVersion,state:'ready',indexedFiles:input.files.length,mode:'hybrid'};},async search(input,env){calls.push(['search',input,env]);return {engine:'zg',knowledgeId:input.knowledgeId,sourceVersion:input.sourceVersion,indexId:'index-'+input.sourceVersion,mode:input.mode,results:[],readonly:true};}};
  const owner={ctx,store,policy:()=>policy,zg:engine},service=new KnowledgeService(owner);return {fs,ctx,store,service,engine,calls,owner};
}
const create=async f=>(await f.service.execute({action:'knowledge.create',name:'Shared code'},user)).knowledge;
const upload=async(f,k,extra={})=>f.service.upload({knowledgeId:k.id,expectedRevision:k.revision,name:'code.md',bytes:Buffer.from('# Example\nButton primary color green\nShared component docs\n'),...extra},user);
const index=async(f,k,extra={})=>f.service.execute({action:'knowledge.index',knowledgeId:k.id,expectedRevision:k.revision,...extra},user);
const status=async(f,k)=>f.service.execute({action:'knowledge.status',knowledgeId:k.id},user);
async function ready(f){let value=await upload(f,await create(f));await index(f,value.knowledge);await f.service.waitForIdle(value.knowledge.id);return {...await status(f,value.knowledge),document:value.document};}
async function reference(f,k){const project=await f.store.projectCreate({name:'Project'}),{reference}=await f.service.execute({action:'knowledge.reference',projectId:project.id,knowledgeId:k.id},user);return {project,reference,env:{task:{projectId:project.id,refs:[{kind:'knowledge',readonly:true,reference}]},policy}};}
async function original(f,k,doc){const {value}=await f.service.record(k.id);return f.service.original(value,f.service.document(value,doc.id));}
function hits(f,doc,extra={}){f.engine.search=async(input,env)=>{f.calls.push(['search',input,env]);return {engine:'zg',knowledgeId:input.knowledgeId,sourceVersion:input.sourceVersion,indexId:'index-'+input.sourceVersion,mode:input.mode,results:[{documentId:doc.id,path:doc.relativePath,startLine:2,endLine:2,snippet:'untrusted helper snippet',score:0.8,matchedBy:'fts',...extra}],readonly:true};};}
async function resource(f,url,extra={}){const req={url,method:'GET',...extra},res={writeHead(status,headers){this.status=status;this.headers=headers;},end(body){this.body=body;}};return {...res,handled:await f.service.handleResource(req,res),...res};}

test('arbitrary original bytes persist independently of runtime, without invented extraction',async()=>{
  const f=fixture(),k=await create(f),bytes=Buffer.from([0,255,0,128,13,10]),value=await upload(f,k,{name:'photo.png',mimeType:'image/png',bytes,relativePath:'folder/photo.png'});
  assert.equal(value.document.searchable,false);assert.equal(value.document.status,'unsupported');assert.equal(value.document.projectionReason,'format-not-extracted');assert.equal(value.knowledge.contentRevision,2);assert.equal(f.calls.length,0);assert.deepEqual(await original(f,value.knowledge,value.document),bytes);
  const restarted=new KnowledgeService(f.owner);const got=await restarted.execute({action:'knowledge.get',knowledgeId:k.id},user);assert.equal(got.documents[0].sha256,value.document.sha256);assert.ok(!JSON.stringify(got).includes('connectionIdentity'));assert.ok(!JSON.stringify(got).includes('viking://'));
});

test('64 MiB exact original boundary, bounded base64 chunks and empty bytes are lossless',async()=>{
  const f=fixture(),k=await create(f),bytes=Buffer.alloc(MAX_KNOWLEDGE_FILE_BYTES,0xa7);let v=await upload(f,k,{name:'binary.bin',bytes});assert.equal(v.document.bytes,MAX_KNOWLEDGE_FILE_BYTES);const saved=(await f.service.record(k.id)).value.documents[0];assert.equal(saved.chunks.length,86);assert.deepEqual(await original(f,v.knowledge,v.document),bytes);
  await assert.rejects(upload(f,v.knowledge,{bytes:Buffer.alloc(MAX_KNOWLEDGE_FILE_BYTES+1)}),{code:'UPLOAD_TOO_LARGE'});v=await upload(f,v.knowledge,{bytes:Buffer.alloc(0)});assert.deepEqual(await original(f,v.knowledge,v.document),Buffer.alloc(0));
});

test('UTF-8 projections are capped, hash checked, and do not pretend to parse PDF or invalid text',async()=>{
  const f=fixture();let k=await create(f),v=await upload(f,k,{bytes:Buffer.from('x'.repeat(LOCAL_PROJECTION_BYTES-1)+'中文 trailing')});assert.equal(v.document.searchable,true);assert.equal(v.document.projection.truncated,true);assert.ok(v.document.projection.bytes<=LOCAL_PROJECTION_BYTES);assert.equal(v.document.projection.characters,LOCAL_PROJECTION_BYTES-1);
  for(const extra of [{name:'guide.pdf',mimeType:'application/pdf',bytes:Buffer.from('PDF plaintext is not extracted')},{name:'broken.txt',bytes:Buffer.from([0xff])},{name:'nulls.js',bytes:Buffer.from('a\0b')}]){v=await upload(f,v.knowledge,extra);assert.equal(v.document.searchable,false);}
  const doc=(await f.service.record(k.id)).value.documents[0],target=await f.service.target(k.id,`projections/${doc.id}.txt`);f.fs.put(target,'changed');await assert.rejects(f.service.projection((await f.service.record(k.id)).value,doc),{code:'RESOURCE_CHANGED'});
});

test('traversal and private paths are rejected before storing files or indexing',async()=>{
  const f=fixture(),k=await create(f),before=f.fs.writes.length;
  for(const relativePath of ['../secret','/absolute','folder/../secret','a\\b','a//b','a/./b','a/\0b'])await assert.rejects(upload(f,k,{relativePath}),{code:'INVALID_PATH'});
  for(const relativePath of ['.env','src/.git/config','node_modules/pkg/readme.md','src/credentials.json','secrets.txt','key.pem','id_rsa','deep/.npmrc'])await assert.rejects(upload(f,k,{relativePath}),{code:'PRIVATE_KNOWLEDGE_PATH'});
  await assert.rejects(upload(f,k,{name:'.env',relativePath:'public.txt'}),{code:'PRIVATE_KNOWLEDGE_PATH'});assert.equal(f.fs.writes.length,before);assert.equal(f.calls.length,0);
});

test('logical revision and provider CAS preserve a concurrent metadata winner',async()=>{
  const f=fixture(),k=await create(f),v=await f.service.execute({action:'knowledge.update',knowledgeId:k.id,expectedRevision:1,name:'Renamed'},user);assert.equal(v.knowledge.revision,2);assert.equal(v.knowledge.contentRevision,1);await assert.rejects(upload(f,k),{code:'VERSION_CONFLICT'});
  let fired=false;f.fs.beforeWrite=async target=>{if(!fired&&target.targetKey.endsWith('/knowledge.json')){fired=true;const current=JSON.parse(f.fs.files.get(target.targetKey).bytes);current.name='Winner';current.revision++;current.contentRevision++;f.fs.put(target,JSON.stringify(current));}};
  await assert.rejects(f.service.execute({action:'knowledge.update',knowledgeId:k.id,expectedRevision:2,name:'Loser'},user),{code:'VERSION_CONFLICT'});assert.equal((await f.service.record(k.id)).value.name,'Winner');
});

