  const receipt=await f.service.execute({action:'knowledge.runtime.prepare'},user);assert.equal(receipt.state,'running');assert.equal((await f.service.execute({action:'knowledge.runtime.cancel',jobId:receipt.jobId},user)).state,'cancelled');
