test('explicit unbound references grant only one exact admitted project read, without mounting',async()=>{
  const f=fixture(),v=await upload(f,await create(f)),r=await reference(f,v.knowledge);assert.equal((await f.store.projectGet(r.project.id)).project.workbench,undefined);assert.equal(r.reference.sourceVersion,v.knowledge.contentRevision);assert.equal((await f.service.resolveReference(r.project,r.reference,r.env)).searchableCount,1);
  await assert.rejects(f.service.resolveReference(r.project,r.reference),{code:'SCOPE_DENIED'});const other=await f.store.projectCreate({name:'Other'});await assert.rejects(f.service.resolveReference(other,r.reference,r.env),{code:'SCOPE_DENIED'});await assert.rejects(f.service.resolveReference(r.project,{...r.reference,sourceVersion:999},r.env),{code:'REFERENCE_VERSION_CONFLICT'});await assert.rejects(f.service.resolveReference(r.project,{...r.reference,connectionIdentity:'old'},r.env),{code:'INVALID_INPUT'});
  const q=await upload(f,v.knowledge,{name:'other.md'});await assert.rejects(f.service.resolveReference(r.project,r.reference,r.env),{code:'REFERENCE_VERSION_CONFLICT'});assert.ok(q.knowledge.contentRevision>r.reference.sourceVersion);
});

