test('search uses the real engine contract in read-only policy, validates source and grounds citations in projections',async()=>{
  const f=fixture(),v=await ready(f),r=await reference(f,v.knowledge);hits(f,v.document);const writes=f.fs.writes.length;for(const requestedMode of ['bm25','semantic','hybrid']){const result=await f.service.execute({action:'knowledge.search',reference:r.reference,query:'Button',mode:requestedMode},r.env);assert.equal(result.engine,'zg');assert.equal(result.mode,requestedMode);assert.equal(result.results[0].documentId,v.document.id);assert.match(result.results[0].snippet,/Button primary color green/);assert.ok(!result.results[0].snippet.includes('untrusted helper'));assert.equal(result.results[0].line,2);assert.equal(result.results[0].uri,`knowledge://${v.knowledge.id}/${v.document.id}`);}
  assert.equal(f.fs.writes.length,writes);assert.ok(f.calls.filter(c=>c[0]==='search').every(c=>c[2].policy.mode==='read-only'));await assert.rejects(f.service.execute({action:'knowledge.search',reference:r.reference,query:'x'.repeat(4001)},r.env),{code:'INVALID_INPUT'});
});

