test('initialContext performs bounded BM25 recall only, with citations and honest not-indexed warnings',async()=>{
  const f=fixture(),v=await ready(f),r=await reference(f,v.knowledge);hits(f,v.document);const value=await f.service.initialContext(r.project,[r.reference],{...user,query:'Button primary'});assert.equal(value.mode,'bm25');assert.equal(value.citations.length,1);assert.match(value.text,/Button primary color green/);assert.ok(JSON.stringify(value).length<=16000);assert.equal(f.calls.filter(c=>c[0]==='search').at(-1)[1].mode,'bm25');assert.equal(value.warnings.length,0);
  const other=await upload(f,await create(f)),q=await reference(f,other.knowledge);const warned=await f.service.initialContext(q.project,[q.reference],{...user,query:'Button'});assert.equal(warned.citations.length,0);assert.match(warned.warnings[0],/index/i);assert.ok(!warned.text.includes('primary color green'));
  f.engine.search=async()=>{throw Object.assign(new Error('Native policy does not allow temporary query storage'),{code:'ZG_READONLY_SCRATCH_UNAVAILABLE'});};const unavailable=await f.service.initialContext(r.project,[r.reference],{...user,query:'Button'});assert.equal(unavailable.citations.length,0);assert.match(unavailable.warnings[0],/temporary query storage/);const read=await f.service.execute({action:'knowledge.read',reference:r.reference,documentId:v.document.id,limit:9},r.env);assert.equal(read.text,'# Example');
});

test('original capability route is owner-only, verifies hashes and never executes uploaded HTML',async()=>{
  const f=fixture(),v=await upload(f,await create(f),{name:'script.html',mimeType:'text/html',bytes:Buffer.from('<script>bad()</script>')}),doc=await f.service.execute({action:'knowledge.document.get',knowledgeId:v.knowledge.id,documentId:v.document.id},user);let result=await resource(f,doc.originalUrl);assert.equal(result.status,200);assert.equal(result.headers['Content-Type'],'application/octet-stream');assert.match(result.headers['Content-Disposition'],/^attachment/);assert.match(result.headers['Content-Security-Policy'],/sandbox/);assert.deepEqual(result.body,Buffer.from('<script>bad()</script>'));
  assert.equal((await resource(f,doc.originalUrl,{method:'HEAD'})).body,undefined);assert.equal((await resource(f,doc.originalUrl,{method:'POST'})).status,405);f.ctx.connection.admit=()=>({peer:{principal:{kind:'agent'}}});assert.equal((await resource(f,doc.originalUrl)).status,403);f.ctx.connection.admit=()=>({peer:{principal:{kind:'owner'}}});const chunk=await f.service.target(v.knowledge.id,`originals/${v.document.id}/0000.base64`);f.fs.put(chunk,Buffer.from('tampered').toString('base64'));assert.equal((await resource(f,doc.originalUrl)).status,409);await f.service.dispose();assert.equal((await resource(f,doc.originalUrl)).status,403);assert.equal((await resource(f,'/unrelated')).handled,false);
});

test('canonical aliases cannot move originals or projections to another knowledge library',async()=>{
  const f=fixture(),v=await upload(f,await create(f)),other=await create(f),foreign=`${f.store.root}/knowledge/${other.id}/secret.txt`;f.fs.put(foreign,'SECRET');f.fs.aliases.set(`${f.store.root}/knowledge/${v.knowledge.id}/projections/${v.document.id}.txt`,foreign);const saved=(await f.service.record(v.knowledge.id)).value;await assert.rejects(f.service.projection(saved,f.service.document(saved,v.document.id)),{code:'REFERENCE_SCOPE'});assert.ok(!f.fs.reads.includes(foreign));f.fs.aliases.clear();f.fs.aliases.set(`${f.store.root}/knowledge/${v.knowledge.id}`,`${f.store.root}/knowledge/${other.id}`);await assert.rejects(f.service.record(v.knowledge.id),{code:'REFERENCE_SCOPE'});
});

test('compact list can include archived libraries without document manifests; renames keep content refs valid',async()=>{
  const f=fixture(),v=await ready(f),r=await reference(f,v.knowledge);const renamed=await f.service.execute({action:'knowledge.update',knowledgeId:v.knowledge.id,expectedRevision:v.knowledge.revision,name:'New display name'},user);assert.equal(renamed.knowledge.contentRevision,v.knowledge.contentRevision);assert.equal(renamed.knowledge.index.state,'ready');assert.equal((await f.service.resolveReference(r.project,r.reference,r.env)).name,'New display name');
  const listed=await f.service.execute({action:'knowledge.list'},user);assert.equal(listed.knowledge[0].documentCount,1);assert.equal(listed.knowledge[0].searchableCount,1);assert.equal(listed.knowledge[0].documents,undefined);assert.ok(!JSON.stringify(listed).includes('chunks'));
  await f.service.execute({action:'knowledge.archive',knowledgeId:v.knowledge.id,expectedRevision:renamed.knowledge.revision},user);assert.equal((await f.service.execute({action:'knowledge.list'},user)).knowledge.length,0);const all=await f.service.execute({action:'knowledge.list',includeArchived:true},user);assert.equal(all.knowledge.length,1);assert.equal(all.knowledge[0].archived,true);await f.service.execute({action:'knowledge.archive',knowledgeId:v.knowledge.id,expectedRevision:all.knowledge[0].revision,archived:false},user);assert.equal((await f.service.execute({action:'knowledge.list'},user)).knowledge.length,1);
});

test('one damaged knowledge library becomes an unavailable list row; explicit get and abort remain strict',async()=>{
  const f=fixture(),good=await create(f),bad=await create(f),target=await f.service.target(bad.id,'knowledge.json');f.fs.put(target,'malformed json');let result=await f.service.execute({action:'knowledge.list'},user);assert.equal(result.knowledge.length,2);assert.equal(result.knowledge.find(k=>k.id===good.id).unavailable,undefined);assert.equal(result.knowledge.find(k=>k.id===bad.id).unavailable,true);assert.equal(result.errors[0].knowledgeId,bad.id);await assert.rejects(f.service.execute({action:'knowledge.get',knowledgeId:bad.id},user),{code:'INVALID_DOCUMENT'});
  f.fs.put(target,'null');result=await f.service.execute({action:'knowledge.list'},user);assert.equal(result.knowledge.find(k=>k.id===bad.id).error.code,'INVALID_DOCUMENT');const controller=new AbortController();controller.abort();await assert.rejects(f.service.execute({action:'knowledge.list'},{...user,signal:controller.signal}),error=>error.name==='AbortError');
});

test('batch import builds exactly one automatic BM25 index without a model cache or preparation call',async()=>{
  const f=fixture(),k=await create(f);f.engine.runtimeStatus=async()=>({engine:'zg',available:true,model:{state:'missing'},indexRequiresModel:false});const originalIndex=f.engine.index;f.engine.index=async(input,env)=>({...await originalIndex(input,env),mode:'bm25',backend:'zvec-fts',vectorEmbedding:false});
  const result=await f.service.importFiles({knowledgeId:k.id,expectedRevision:k.revision,source:{kind:'local',directory:'/Users/private/never-store-this'},files:[{name:'a.md',relativePath:'docs/a.md',bytes:Buffer.from('alpha account cache')},{name:'b.js',relativePath:'src/b.js',bytes:Buffer.from('export const alpha = true;')}]},user);
  assert.equal(result.importedCount,2);assert.equal(result.failedCount,0);assert.equal(result.succeeded.length,2);assert.equal(result.knowledge.lastImport.state,'stored');assert.equal(result.index.state,'indexing');assert.equal(result.index.sourceVersion,result.knowledge.contentRevision);await f.service.waitForIdle(k.id);const finished=await status(f,k);assert.equal(finished.index.state,'ready');assert.equal(finished.index.mode,'bm25');assert.equal(finished.index.backend,'zvec-fts');assert.equal(finished.index.vectorEmbedding,false);assert.equal(f.calls.filter(c=>c[0]==='index').length,1);assert.equal(f.calls.filter(c=>c[0]==='setup').length,0);assert.ok(!JSON.stringify(finished).includes('never-store-this'));const summary=(await f.service.execute({action:'knowledge.list'},user)).knowledge[0];assert.equal(summary.lastImport.importedCount,2);assert.equal(summary.lastImport.documentIds,undefined);assert.equal(summary.lastImport.failures,undefined);
});

test('browser batch defers indexing across uploads, finalizes once, and preserves exact CAS semantics',async()=>{
  const f=fixture(),k=await create(f),start=await f.service.execute({action:'knowledge.import.begin',knowledgeId:k.id,expectedRevision:k.revision},user);assert.equal(start.knowledge.contentRevision,k.contentRevision);let saved=await upload(f,start.knowledge,{batchId:start.batchId,name:'one.md'});assert.equal(f.calls.filter(c=>c[0]==='index').length,0);await assert.rejects(index(f,saved.knowledge),{code:'IMPORT_IN_PROGRESS'});await assert.rejects(upload(f,saved.knowledge,{name:'foreign.md'}),{code:'IMPORT_IN_PROGRESS'});const previous=saved.knowledge;saved=await upload(f,saved.knowledge,{batchId:start.batchId,name:'two.md'});await assert.rejects(f.service.execute({action:'knowledge.import.complete',knowledgeId:k.id,batchId:start.batchId,expectedRevision:previous.revision},user),{code:'VERSION_CONFLICT'});
  const result=await f.service.execute({action:'knowledge.import.complete',knowledgeId:k.id,batchId:start.batchId,expectedRevision:saved.knowledge.revision},user);await f.service.waitForIdle(k.id);assert.equal(result.importedCount,2);assert.equal(f.calls.filter(c=>c[0]==='index').length,1);const repeated=await f.service.execute({action:'knowledge.import.complete',knowledgeId:k.id,batchId:start.batchId,expectedRevision:saved.knowledge.revision},user);assert.equal(repeated.importedCount,2);assert.equal(f.calls.filter(c=>c[0]==='index').length,1);await assert.rejects(upload(f,repeated.knowledge,{batchId:start.batchId}),{code:'IMPORT_BATCH_CLOSED'});
});

