test('automatic index failure is visible and a batch containing only binary originals never claims queued or ready',async()=>{
  const f=fixture(),k=await create(f);f.engine.index=async()=>{throw Object.assign(new Error('sensitive native output'),{code:'ZG_INDEX_FAILED'});};const result=await f.service.importFiles({knowledgeId:k.id,expectedRevision:k.revision,files:[{name:'a.txt',bytes:Buffer.from('actual UTF8 text')}]},user);await f.service.waitForIdle(k.id);assert.equal((await status(f,k)).index.state,'failed');assert.deepEqual(await original(f,result.knowledge,result.documents[0]),Buffer.from('actual UTF8 text'));const empty=await create(f),binary=await f.service.importFiles({knowledgeId:empty.id,expectedRevision:empty.revision,files:[{name:'photo.png',mimeType:'image/png',bytes:Buffer.from([0,255,3])}]},user);assert.equal(binary.importedCount,1);assert.equal(binary.indexError.code,'KNOWLEDGE_NOT_SEARCHABLE');assert.equal(binary.knowledge.index.state,'not-indexed');assert.equal(binary.documents[0].searchable,false);const restored=await f.service.execute({action:'knowledge.get',knowledgeId:empty.id},user);assert.equal(restored.knowledge.index.error.code,'KNOWLEDGE_NOT_SEARCHABLE');assert.equal(restored.knowledge.lastImport.indexError.code,'KNOWLEDGE_NOT_SEARCHABLE');
  const missing=await create(f);f.engine.runtimeStatus=async()=>({available:false,model:{state:'missing'}});const unavailable=await f.service.importFiles({knowledgeId:missing.id,expectedRevision:missing.revision,files:[{name:'valid.txt',bytes:Buffer.from('saved text')}]},user);assert.equal(unavailable.indexError.code,'ZG_RUNTIME_UNAVAILABLE');const persisted=await status(f,missing);assert.equal(persisted.index.state,'failed');assert.equal(persisted.index.error.code,'ZG_RUNTIME_UNAVAILABLE');
});

