test('beginning a new batch supersedes a running old index without inter-file revision races',async()=>{
  const f=fixture(),v=await upload(f,await create(f)),realIndex=f.engine.index;let first=true;f.engine.index=async(input,env)=>{if(!first)return realIndex(input,env);first=false;return new Promise((_resolve,reject)=>env.signal.addEventListener('abort',()=>reject(Object.assign(new Error('cancelled'),{code:'ZG_ABORTED'})),{once:true}));};const running=await index(f,v.knowledge),start=await f.service.beginImport({knowledgeId:v.knowledge.id,expectedRevision:running.knowledge.revision},user);const one=await upload(f,start.knowledge,{batchId:start.batchId,name:'new.md'});await f.service.waitForIdle(v.knowledge.id);assert.equal((await f.service.record(v.knowledge.id)).value.revision,one.knowledge.revision);const result=await f.service.completeImport({knowledgeId:v.knowledge.id,batchId:start.batchId,expectedRevision:one.knowledge.revision},user);await f.service.waitForIdle(v.knowledge.id);const done=await status(f,v.knowledge);assert.equal(done.index.state,'ready');assert.equal(done.index.sourceVersion,result.knowledge.contentRevision);assert.equal(f.calls.filter(c=>c[0]==='index').length,1);
});

