test('reimport updates each active relative path and retains previous original bytes and owner capabilities permanently',async()=>{
  const f=fixture(),k=await create(f),first=await f.service.importFiles({knowledgeId:k.id,expectedRevision:k.revision,autoIndex:false,files:[{name:'guide.md',relativePath:'docs/guide.md',bytes:Buffer.from('Original version')}]},user),oldDoc=first.documents[0],oldCap=await f.service.execute({action:'knowledge.document.get',knowledgeId:k.id,documentId:oldDoc.id},user),prior=await reference(f,first.knowledge);const second=await f.service.importFiles({knowledgeId:k.id,expectedRevision:first.knowledge.revision,replacePaths:true,files:[{name:'guide.md',relativePath:'docs/guide.md',bytes:Buffer.from('Updated version')}]},user);await f.service.waitForIdle(k.id);assert.equal(second.knowledge.documents.length,1);assert.notEqual(second.documents[0].id,oldDoc.id);assert.equal(second.importedCount,1);assert.equal(f.calls.filter(call=>call[0]==='index').length,1);const retained=await f.service.execute({action:'knowledge.document.get',knowledgeId:k.id,documentId:oldDoc.id},user);assert.equal(retained.document.status,'retained');assert.equal(retained.document.retained,true);assert.deepEqual((await resource(f,oldCap.originalUrl)).body,Buffer.from('Original version'));assert.deepEqual(await original(f,second.knowledge,second.documents[0]),Buffer.from('Updated version'));await assert.rejects(f.service.resolveReference(prior.project,prior.reference,prior.env),{code:'REFERENCE_VERSION_CONFLICT'});
  const fresh=await reference(f,second.knowledge),read=await f.service.execute({action:'knowledge.read',reference:fresh.reference,path:'docs/guide.md'},fresh.env);assert.equal(read.text,'Updated version');await assert.rejects(f.service.execute({action:'knowledge.read',reference:fresh.reference,documentId:oldDoc.id},fresh.env),{code:'NOT_FOUND'});
});

