  const f=fixture(),k=await create(f),first=await f.service.importFiles({knowledgeId:k.id,expectedRevision:k.revision,autoIndex:false,files:[{name:'guide.md',bytes:Buffer.from('Retain this old document')}]},user);f.fs.beforeWrite=async target=>{if(target.targetKey.includes('/projections/'))throw Object.assign(new Error('Cannot write replacement'),{code:'FS_PERMISSION_DENIED'});};const failed=await f.service.importFiles({knowledgeId:k.id,expectedRevision:first.knowledge.revision,replacePaths:true,files:[{name:'guide.md',bytes:Buffer.from('Failed replacement')}]},user);assert.equal(failed.importedCount,0);assert.equal(failed.failedCount,1);assert.equal(failed.knowledge.documents.length,1);assert.equal(failed.knowledge.documents[0].id,first.documents[0].id);assert.deepEqual(await original(f,failed.knowledge,first.documents[0]),Buffer.from('Retain this old document'));f.fs.beforeWrite=null;
